--- a/src/Reminders/ReminderQuery.cs
+++ b/src/Reminders/ReminderQuery.cs
@@ -9,13 +9,25 @@ public class ReminderQuery
     private readonly ClinicContext _db;

     public ReminderQuery(ClinicContext db) => _db = db;

-    public IQueryable<Reminder> Pending() =>
-        _db.Reminders.Where(r => !r.Sent);
+    public IQueryable<Reminder> Pending() =>
+        _db.Reminders.Where(r => !r.Sent);
+
+    public async Task<List<Reminder>> OverdueAsync(int limit = 100)
+    {
+        var now = DateTime.Now;
+
+        return await _db.Reminders
+            .Where(r => !r.Sent && r.DueAt <= now)
+            .OrderBy(r => r.DueAt)
+            .Take(limit)
+            .ToListAsync();
+    }

     public Task<int> CountAsync() => _db.Reminders.CountAsync();
 }
